import uuid
from datetime import datetime

class SharedMemory:
    def __init__(self):
        self.client = Client(Settings(anonymized_telemetry=False))
        self.col = self.client.get_or_create_collection('agent_memory', metadata={'hnsw:space': 'cosine'})
    def store(self, agent_id, content, meta=None):
