from tenacity import retry, stop_after_attempt, wait_exponential, retry_if_exception_type

class LLMRateLimitError(Exception): pass
class AgentTimeoutError(Exception): pass

@retry(
    stop=stop_after_attempt(3),
    wait=wait_exponential(multiplier=1, min=2, max=30),
    retry=retry_if_exception_type((LLMRateLimitError, AgentTimeoutError))
)
async def call_agent(agent, prompt):
    try:
        return await agent.ainvoke(prompt)
    except RateLimitError:
        raise LLMRateLimitError('Rate limit')
    except asyncio.TimeoutError:
        raise AgentTimeoutError('Timeout')

Configuracao tipica: 3 tentativas, backoff exponencial (2s, 4s, 8s), retry so em erros transientes. Para multi-agente: aplique retry por agente. Se falha apos retry, faca fallback para agente alternativo.

from dataclasses import dataclass, field
import asyncio
from datetime import datetime

@dataclass(order=True)
class PrioritizedTask:
    priority: int  # Menor = mais urgente
    created_at: datetime = field(compare=True)
    task_id: str = field(compare=False)
    description: str = field(compare=False)
    agent_type: str = field(compare=False)

class TaskDispatcher:
    def __init__(self):
        self.queue = asyncio.PriorityQueue()
        self.agents = {'researcher': [], 'coder': [], 'analyst': []}
    async def submit(self, task): await self.queue.put(task)
    async def dispatch(self):
        while True:
            task = await self.queue.get()
            available = [a for a in self.agents[task.agent_type] if not a.busy]
            if available:
                asyncio.create_task(available[0].process(task))
            else:
                await self.queue.put(task)
                await asyncio.sleep(1)

Prioridade: 1=critico, 5=normal, 10=baixo. PriorityQueue ordena por prioridade, depois por timestamp (FIFO dentro da mesma prioridade).

