import asyncio
from datetime import datetime

class Blackboard:
    def __init__(self):
        self.data = {}; self.lock = asyncio.Lock()
    async def write(self, key, value, agent_id):
        async with self.lock:
            self.data[key] = {'value': value, 'author': agent_id, 'ts': datetime.now().isoformat()}
    async def read(self, key): return self.data.get(key, {}).get('value')
    async def read_all(self): return dict(self.data)

class BlackboardAgent:
    def __init__(self, agent_id, blackboard, interests, contributions):
        self.agent_id = agent_id; self.bb = blackboard
        self.interests = interests; self.contributions = contributions
    async def run(self):
        while True:
            data = await self.bb.read_all()
            if all(k in data for k in self.interests):
                result = process(data, self.contributions)
                for k, v in result.items(): await self.bb.write(k, v, self.agent_id)
                break
            await asyncio.sleep(0.5)

Vantagem: desacoplamento total (agentes nao se conhecem). Desvantagem: ordem nao garantida, polling necessario.

import asyncio, time
from enum import Enum

class CircuitState(Enum):
    CLOSED = 'closed'; OPEN = 'open'; HALF_OPEN = 'half_open'

class CircuitBreaker:
    def __init__(self, failure_threshold=3, recovery_timeout=30):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.state = CircuitState.CLOSED
        self.failure_count = 0; self.last_failure_time = 0
    async def call(self, func, *args, **kwargs):
        if self.state == CircuitState.OPEN:
            if time.time() - self.last_failure_time > self.recovery_timeout:
                self.state = CircuitState.HALF_OPEN
            else:
                raise Exception('Circuit breaker OPEN')
        try:
            result = await func(*args, **kwargs)
            if self.state == CircuitState.HALF_OPEN:
                self.state = CircuitState.CLOSED; self.failure_count = 0
            return result
        except Exception:
            self.failure_count += 1; self.last_failure_time = time.time()
            if self.failure_count >= self.failure_threshold:
                self.state = CircuitState.OPEN
            raise

Estados: CLOSED (normal), OPEN (falhou N vezes, rejeita), HALF_OPEN (teste se recuperou). Use um breaker por agente.

Especialistas: Prompt focado em UM dominio. Maior qualidade. Menos hallucination. Mais agentes para gerenciar. Exemplo: researcher, coder, analyst, writer.

Generalistas: Prompt amplo cobrindo multiplos dominios. Flexivel. Mais propenso a hallucination. Menos agentes. Exemplo: agente unico com roteamento interno.

Hibrido (melhor dos dois): Queries simples vao para generalista. Queries complexas roteam para especialistas.

