from langgraph.checkpoint.memory import MemorySaver

class RollbackManager:
    def __init__(self, graph, checkpointer):
        self.graph = graph; self.checkpointer = checkpointer
    def get_checkpoint(self, thread_id, checkpoint_id=None):
        state_history = list(self.graph.get_state_history({'configurable': {'thread_id': thread_id}}))
        if checkpoint_id:
            return next((s for s in state_history if s.config['configurable']['checkpoint_id'] == checkpoint_id), None)
        return state_history
    async def rollback_to(self, thread_id, checkpoint_id):
        config = {'configurable': {'thread_id': thread_id, 'checkpoint_id': checkpoint_id}}
        state = self.graph.get_state(config)
        return state.values

LangGraph salva checkpoints automaticamente a cada no. Use get_state_history para ver todos e rollback_to para restaurar ponto anterior.

