import asyncio
from dataclasses import dataclass
from datetime import datetime

@dataclass
class CostEntry:
    agent_id: str; tokens_in: int; tokens_out: int; model: str; timestamp: datetime

class CostTracker:
    def __init__(self, price_per_1k_input=0.03, price_per_1k_output=0.06):
        self.entries = []
        self.price_in = price_per_1k_input
        self.price_out = price_per_1k_output
    def record(self, agent_id, tokens_in, tokens_out, model='gpt-4'):
        self.entries.append(CostEntry(agent_id, tokens_in, tokens_out, model, datetime.now()))
    def cost_by_agent(self) -> dict:
        costs = {}
        for e in self.entries:
            c = (e.tokens_in * self.price_in + e.tokens_out * self.price_out) / 1000
            costs[e.agent_id] = costs.get(e.agent_id, 0) + c
        return costs
    def total_cost(self) -> float:
        return sum((e.tokens_in * self.price_in + e.tokens_out * self.price_out) / 1000 for e in self.entries)
    def budget_remaining(self, budget: float) -> float:
        return budget - self.total_cost()

tracker = CostTracker()
tracker.record('researcher', 500, 200, 'gpt-4')
tracker.record('coder', 800, 400, 'gpt-4')
print(tracker.cost_by_agent())  # {'researcher': 0.027, 'coder': 0.048}
print(tracker.total_cost())  # 0.075

