from langgraph.graph import StateGraph, START, END
from langgraph.types import Command

class TimeoutState(TypedDict):
    messages: list; result: str; timed_out_agents: list[str]

def agent_with_timeout(agent_id, timeout_seconds=30):
    async def node(state):
        if agent_id in state.get('timed_out_agents', []):
            return Command(goto='fallback', update={'result': 'Usando resposta de fallback'})
        try:
            result = await asyncio.wait_for(
                call_agent(agent_id, state),
                timeout=timeout_seconds
            )
            return {'result': result}
        except asyncio.TimeoutError:
            timed = state.get('timed_out_agents', []) + [agent_id]
            return Command(goto='fallback', update={'timed_out_agents': timed, 'result': f'{agent_id} demorou demais'})
    return node

Use asyncio.wait_for para timeout por chamada. Registre timed_out_agents para nao tentar o mesmo agente de novo. Faca fallback para agente mais simples (menor latencia) ou para resposta cacheada.

from langgraph.graph import StateGraph, START, END

class ConditionalState(TypedDict):
    query: str; complexity: str; result: str

def complexity_analyzer(state):
    query = state['query']
    word_count = len(query.split())
    if word_count > 50 or any(w in query for w in ['analise', 'compare', 'explique detalhadamente']):
        return {'complexity': 'high'}
    return {'complexity': 'low'}

def router(state):
    if state['complexity'] == 'high':
        return 'complex_agent'
    return 'simple_agent'

def complex_agent(state): return {'result': f'Resposta detalhada para: {state["query"]}'}
def simple_agent(state): return {'result': f'Resposta rapida para: {state["query"]}'}

builder = StateGraph(ConditionalState)
builder.add_node('analyzer', complexity_analyzer)
builder.add_node('complex_agent', complex_agent)
builder.add_node('simple_agent', simple_agent)
builder.add_edge(START, 'analyzer')
builder.add_conditional_edges('analyzer', router)
builder.add_edge('complex_agent', END)
builder.add_edge('simple_agent', END)
graph = builder.compile()

Analisa complexidade primeiro, depois roteia. Alta complexidade: agente com modelo maior e mais tempo. Baixa complexidade: agente rapido e barato. Economia de ate 70% em tokens.

