import json
from datetime import datetime
from typing import Any

class AuditLog:
    def __init__(self):
        self.entries = []
    def log(self, agent_id: str, action: str, input_data: Any, output_data: Any, metadata: dict = None):
        entry = {
            'timestamp': datetime.now().isoformat(),
            'agent_id': agent_id,
            'action': action,
            'input_hash': hash(str(input_data)),
            'output_hash': hash(str(output_data)),
            'metadata': metadata or {}
        }
        self.entries.append(entry)
    def get_agent_trace(self, agent_id: str) -> list:
        return [e for e in self.entries if e['agent_id'] == agent_id]
    def get_full_trace(self) -> list:
        return self.entries
    def export(self, filepath: str):
        with open(filepath, 'w') as f:
            json.dump(self.entries, f, indent=2, default=str)

class AuditedAgent:
    def __init__(self, agent_id, agent, audit: AuditLog):
        self.agent_id = agent_id; self.agent = agent; self.audit = audit
    async def run(self, input_data):
        self.audit.log(self.agent_id, 'input', input_data, None)
        result = await self.agent.ainvoke(input_data)
        self.audit.log(self.agent_id, 'output', input_data, result)
        return result

Para compliance, armazene hashes (nao conteudo completo) e permita reconstituicao via checkpoints. Exporte para JSON para analise externa.

import asyncio
from dataclasses import dataclass

@dataclass
class AgentWorker:
    id: str; agent: object; busy: bool = False; tasks_completed: int = 0

class LoadBalancer:
    def __init__(self, workers: list[AgentWorker]):
        self.workers = workers; self.queue = asyncio.Queue()
    def _select_worker(self, strategy='least_busy') -> AgentWorker:
        available = [w for w in self.workers if not w.busy]
        if not available: return None
        if strategy == 'least_busy':
            return min(available, key=lambda w: w.tasks_completed)
        elif strategy == 'random':
            import random; return random.choice(available)
        elif strategy == 'round_robin':
            return available[self._rr_counter % len(available)]
    async def submit(self, task):
        await self.queue.put(task)
    async def run(self):
        while True:
            task = await self.queue.get()
            worker = self._select_worker()
            if worker:
                worker.busy = True
                try:
                    result = await worker.agent.ainvoke(task)
                    worker.tasks_completed += 1
                finally:
                    worker.busy = False
            else:
                await self.queue.put(task)
                await asyncio.sleep(1)

Estrategias: least_busy (menos tarefas completadas), random, round_robin. Ideal quando multiplos agentes podem processar o mesmo tipo de tarefa.
